CREATE TYPE public.app_role AS ENUM ('customer','admin','delivery_partner','vendor');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '', phone text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role; ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,role public.app_role NOT NULL DEFAULT 'customer',UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role; ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE POLICY role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.has_role(auth.uid(),'admin'));
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.new_customer() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,name,phone) VALUES(NEW.id,COALESCE(NEW.raw_user_meta_data->>'name',''),COALESCE(NEW.raw_user_meta_data->>'phone','')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,'customer'); RETURN NEW; END $$;
CREATE TRIGGER create_customer AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.new_customer();
CREATE TABLE public.stores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,location text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true,owner_id uuid,opens text NOT NULL DEFAULT '08:00',closes text NOT NULL DEFAULT '22:00');
GRANT SELECT ON public.stores TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.stores TO authenticated; GRANT ALL ON public.stores TO service_role; ALTER TABLE public.stores ENABLE ROW LEVEL SECURITY; CREATE POLICY stores_public ON public.stores FOR SELECT USING(active); CREATE POLICY stores_admin ON public.stores FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.categories (id text PRIMARY KEY,name text NOT NULL,image_index integer NOT NULL DEFAULT 0,sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.categories TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role; ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY; CREATE POLICY categories_public ON public.categories FOR SELECT USING(true); CREATE POLICY categories_admin ON public.categories FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,brand text NOT NULL DEFAULT 'KASHUR KART',unit text NOT NULL DEFAULT '1 pack',price numeric(10,2) NOT NULL CHECK(price>=0),mrp numeric(10,2) NOT NULL CHECK(mrp>=price),stock integer NOT NULL DEFAULT 100 CHECK(stock>=0),category_id text REFERENCES public.categories(id),store_id uuid REFERENCES public.stores(id),image_index integer NOT NULL DEFAULT 0,image_url text,description text NOT NULL DEFAULT 'Fresh quality, carefully selected for your everyday needs.',rating numeric(2,1) NOT NULL DEFAULT 4.5,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role; ALTER TABLE public.products ENABLE ROW LEVEL SECURITY; CREATE POLICY products_public ON public.products FOR SELECT USING(active); CREATE POLICY products_admin ON public.products FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.delivery_areas (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,active boolean NOT NULL DEFAULT true,eta text NOT NULL DEFAULT '30–60 minutes',fee numeric NOT NULL DEFAULT 30,free_above numeric NOT NULL DEFAULT 499);
GRANT SELECT ON public.delivery_areas TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.delivery_areas TO authenticated; GRANT ALL ON public.delivery_areas TO service_role; ALTER TABLE public.delivery_areas ENABLE ROW LEVEL SECURITY; CREATE POLICY areas_public ON public.delivery_areas FOR SELECT USING(active); CREATE POLICY areas_admin ON public.delivery_areas FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.delivery_slots (id text PRIMARY KEY,label text NOT NULL,active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.delivery_slots TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.delivery_slots TO authenticated; GRANT ALL ON public.delivery_slots TO service_role; ALTER TABLE public.delivery_slots ENABLE ROW LEVEL SECURITY; CREATE POLICY slots_public ON public.delivery_slots FOR SELECT USING(active); CREATE POLICY slots_admin ON public.delivery_slots FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,name text NOT NULL,phone text NOT NULL,house text NOT NULL,street text NOT NULL,city text NOT NULL,landmark text NOT NULL DEFAULT '',label text NOT NULL DEFAULT 'Home');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.addresses TO authenticated; GRANT ALL ON public.addresses TO service_role; ALTER TABLE public.addresses ENABLE ROW LEVEL SECURITY; CREATE POLICY own_addresses ON public.addresses FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.coupons (code text PRIMARY KEY,title text NOT NULL,kind text NOT NULL DEFAULT 'fixed' CHECK(kind IN ('fixed','percent')),value numeric NOT NULL CHECK(value>=0),min_order numeric NOT NULL DEFAULT 0,max_discount numeric NOT NULL DEFAULT 100,expires_at timestamptz NOT NULL DEFAULT now()+interval '1 year',usage_limit integer NOT NULL DEFAULT 1000,used integer NOT NULL DEFAULT 0,active boolean NOT NULL DEFAULT true);
GRANT SELECT ON public.coupons TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.coupons TO authenticated; GRANT ALL ON public.coupons TO service_role; ALTER TABLE public.coupons ENABLE ROW LEVEL SECURITY; CREATE POLICY coupons_public ON public.coupons FOR SELECT USING(active); CREATE POLICY coupons_admin ON public.coupons FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),number text UNIQUE NOT NULL DEFAULT 'KK-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,8)),user_id uuid NOT NULL,status text NOT NULL DEFAULT 'Order Placed' CHECK(status IN ('Order Placed','Confirmed','Preparing','Picked Up','Out for Delivery','Delivered','Cancelled')),address jsonb NOT NULL,slot text NOT NULL DEFAULT 'ASAP',subtotal numeric NOT NULL,delivery_fee numeric NOT NULL,discount numeric NOT NULL DEFAULT 0,total numeric NOT NULL,payment_method text NOT NULL DEFAULT 'Cash on Delivery',partner_id uuid,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role; ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY; CREATE POLICY order_read ON public.orders FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.has_role(auth.uid(),'admin') OR (partner_id=auth.uid() AND public.has_role(auth.uid(),'delivery_partner'))); CREATE POLICY order_admin ON public.orders FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,product_id uuid REFERENCES public.products(id),name text NOT NULL,unit text NOT NULL,price numeric NOT NULL,quantity integer NOT NULL CHECK(quantity>0),image_index integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.order_items TO authenticated; GRANT ALL ON public.order_items TO service_role; ALTER TABLE public.order_items ENABLE ROW LEVEL SECURITY; CREATE POLICY items_read ON public.order_items FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.orders o WHERE o.id=order_id));
CREATE TABLE public.wishlist (user_id uuid NOT NULL,product_id uuid NOT NULL REFERENCES public.products(id) ON DELETE CASCADE,PRIMARY KEY(user_id,product_id));
GRANT SELECT,INSERT,DELETE ON public.wishlist TO authenticated; GRANT ALL ON public.wishlist TO service_role; ALTER TABLE public.wishlist ENABLE ROW LEVEL SECURITY; CREATE POLICY own_wishlist ON public.wishlist FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,title text NOT NULL,body text NOT NULL DEFAULT '',read boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.notifications TO authenticated; GRANT ALL ON public.notifications TO service_role; ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY; CREATE POLICY notifications_read ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid()); CREATE POLICY notifications_update ON public.notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,product_id uuid NOT NULL REFERENCES public.products(id),rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5),comment text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,product_id));
GRANT SELECT ON public.reviews TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.reviews TO authenticated; GRANT ALL ON public.reviews TO service_role; ALTER TABLE public.reviews ENABLE ROW LEVEL SECURITY; CREATE POLICY reviews_public ON public.reviews FOR SELECT USING(true); CREATE POLICY reviews_own ON public.reviews FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.milk_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,product_id uuid NOT NULL REFERENCES public.products(id),quantity integer NOT NULL DEFAULT 1,frequency text NOT NULL DEFAULT 'Daily',paused boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.milk_subscriptions TO authenticated; GRANT ALL ON public.milk_subscriptions TO service_role; ALTER TABLE public.milk_subscriptions ENABLE ROW LEVEL SECURITY; CREATE POLICY subscriptions_own ON public.milk_subscriptions FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE FUNCTION public.place_order(items jsonb,address_id uuid,delivery_slot text,coupon_code text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); a public.addresses; area public.delivery_areas; c public.coupons; p public.products; line jsonb; q integer; sub numeric:=0; fee numeric; disc numeric:=0; oid uuid; BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Please sign in to place an order'; END IF; IF jsonb_array_length(items)=0 OR jsonb_array_length(items)>100 THEN RAISE EXCEPTION 'Your cart is empty or too large'; END IF; SELECT * INTO a FROM public.addresses WHERE id=address_id AND user_id=uid; IF NOT FOUND THEN RAISE EXCEPTION 'Select a valid saved address'; END IF; SELECT * INTO area FROM public.delivery_areas WHERE name=a.city AND active; IF NOT FOUND THEN RAISE EXCEPTION 'Delivery is not available in this area'; END IF; IF delivery_slot<>'ASAP' AND NOT EXISTS(SELECT 1 FROM public.delivery_slots WHERE id=delivery_slot AND active) THEN RAISE EXCEPTION 'Select a valid delivery time'; END IF; FOR line IN SELECT * FROM jsonb_array_elements(items) LOOP q:=(line->>'quantity')::integer; IF q<1 OR q>99 THEN RAISE EXCEPTION 'Invalid quantity'; END IF; SELECT * INTO p FROM public.products WHERE id=(line->>'product_id')::uuid AND active FOR UPDATE; IF NOT FOUND OR p.stock<q THEN RAISE EXCEPTION 'A product is unavailable or has insufficient stock'; END IF; sub:=sub+p.price*q; UPDATE public.products SET stock=stock-q WHERE id=p.id; END LOOP; fee:=CASE WHEN sub>=area.free_above THEN 0 ELSE area.fee END; IF coupon_code<>'' THEN SELECT * INTO c FROM public.coupons WHERE code=upper(coupon_code) AND active FOR UPDATE; IF NOT FOUND OR c.expires_at<now() OR c.used>=c.usage_limit OR sub<c.min_order THEN RAISE EXCEPTION 'Coupon is not valid for this order'; END IF; IF c.code='WELCOME100' AND EXISTS(SELECT 1 FROM public.orders WHERE user_id=uid AND status<>'Cancelled') THEN RAISE EXCEPTION 'This coupon is for your first order only'; END IF; disc:=least(sub,c.max_discount,CASE WHEN c.kind='percent' THEN sub*c.value/100 ELSE c.value END); UPDATE public.coupons SET used=used+1 WHERE code=c.code; END IF; INSERT INTO public.orders(user_id,address,slot,subtotal,delivery_fee,discount,total) VALUES(uid,to_jsonb(a),delivery_slot,sub,fee,disc,sub+fee-disc) RETURNING id INTO oid; FOR line IN SELECT * FROM jsonb_array_elements(items) LOOP SELECT * INTO p FROM public.products WHERE id=(line->>'product_id')::uuid; INSERT INTO public.order_items(order_id,product_id,name,unit,price,quantity,image_index) VALUES(oid,p.id,p.name,p.unit,p.price,(line->>'quantity')::integer,p.image_index); END LOOP; INSERT INTO public.notifications(user_id,title,body) VALUES(uid,'Order placed','Your KASHUR KART order has been received.'); RETURN oid; END $$;
REVOKE ALL ON FUNCTION public.place_order(jsonb,uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.place_order(jsonb,uuid,text,text) TO authenticated;
CREATE FUNCTION public.notify_order_status() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.status<>OLD.status THEN INSERT INTO public.notifications(user_id,title,body) VALUES(NEW.user_id,'Order '||NEW.status,NEW.number||' is now '||lower(NEW.status)||'.'); END IF; RETURN NEW; END $$; CREATE TRIGGER order_status_notification AFTER UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.notify_order_status();
CREATE INDEX orders_user_idx ON public.orders(user_id); CREATE INDEX orders_partner_idx ON public.orders(partner_id); CREATE INDEX items_order_idx ON public.order_items(order_id); CREATE INDEX addresses_user_idx ON public.addresses(user_id); CREATE INDEX products_category_idx ON public.products(category_id);
ALTER PUBLICATION supabase_realtime ADD TABLE public.orders;
